# hypothesis: Concatenate[int, P] injects an int, so a callee whose first parameter is bool is rejected while float is accepted because int promotes to float.
from collections.abc import Callable
from typing import Concatenate, reveal_type


def with_attempt[**P, R](fn: Callable[Concatenate[int, P], R]) -> Callable[P, R]:
    def inner(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(1, *args, **kwargs)
    return inner


def retry[**P, R](fn: Callable[P, R], times: int) -> Callable[P, list[R]]:
    def inner(*args: P.args, **kwargs: P.kwargs) -> list[R]:
        return [fn(*args, **kwargs) for _ in range(times)]
    return inner


@with_attempt
def fetch(attempt: float, url: str, *, timeout: int = 3) -> str:
    return f'{url}#{attempt}/{timeout}'


@with_attempt  # expect-error: int is not assignable to bool
def flag(attempt: bool, name: str) -> str:
    return f'{name}:{attempt}'


repeated = retry(fetch, 2)
reveal_type(fetch)
reveal_type(repeated)
print(fetch('a', timeout=5), repeated('b'), flag('x'))
